import Foundation

/// 生成 shell 环境脚本的纯函数集合，方便在测试中校验。
public enum EnvironmentScript {

    /// 生成完整的 *_env.sh 内容。
    public static func content(
        languageName: String,
        version: String,
        runtimePath: String,
        environmentVariableName: String?,
        pathSuffix: String
    ) -> String {
        let safeName = languageName.replacingOccurrences(of: "\n", with: " ")
        let entry = pathEntry(runtimePath: runtimePath, pathSuffix: pathSuffix)

        var lines = [
            "# \(safeName) Environment Configuration",
            "# Generated by SYFLV",
            "# Active version: \(version)",
            "",
        ]

        let envVarName = (environmentVariableName ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        if !envVarName.isEmpty {
            lines.append("export \(envVarName)=\"\(shellDoubleQuoted(runtimePath))\"")
        }
        lines.append("export PATH=\"\(shellDoubleQuoted(entry)):$PATH\"")
        return lines.joined(separator: "\n") + "\n"
    }

    /// 生成 PATH 条目：运行时根目录 + 配置的 bin 子目录
    public static func pathEntry(runtimePath: String, pathSuffix: String) -> String {
        let suffix = pathSuffix.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        if suffix.isEmpty {
            return runtimePath
        }
        return (runtimePath as NSString).appendingPathComponent(suffix)
    }

    /// 将路径转义后放入 shell 的双引号字符串中
    public static func shellDoubleQuoted(_ value: String) -> String {
        return
            value
            .replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "\"", with: "\\\"")
            .replacingOccurrences(of: "$", with: "\\$")
            .replacingOccurrences(of: "\u{60}", with: "\\\u{60}")
    }
}
